const brute = (a, x) => {
  const i = a.findIndex(v => v >= x)
  return i === -1 ? a.length : i
}

for (let t = 0; t < 2000; t++) {
  const n = Math.floor(Math.random() * 7)
  const a = Array.from({ length: n }, () => Math.floor(Math.random() * 5))
    .sort((p, q) => p - q)
  const x = Math.floor(Math.random() * 7) - 1
  if (lowerBound(a, x) !== brute(a, x)) {
    console.log('mismatch', a, x, lowerBound(a, x), brute(a, x))
    break
  }
}

